// The customer's verdict on a resolved ticket: a whole number from 1 to 5, given once. Who may rate (their own
// organisation only) is checked by the caller, see portal.rateMyTicket.
function rateTicket(store, id, score, { now = new Date() } = {}) {
  const t = mustGet(store, id);
  if (t.status !== STATUS.RESOLVED) throw new Error(`cannot rate a ${t.status} ticket`);
  if (!Number.isInteger(score) || score < 1 || score > 5) throw new Error('a score is a whole number from 1 to 5');
  const rated = store.setRatingOnce(id, { rating: score, rated_at: now.toISOString() });
  if (!rated) throw new Error('this ticket has already been rated');
  if (score <= LOW_SCORE && rated.owner_id) notifyAgent(store, rated.owner_id, { type: 'low_rating', ticketId: id, score });
  return rated;
}
