```js
'use strict';
// Nightly. For each agent: how many ratings their tickets received in the past seven days, and the average score.
// Ratings count for the ticket's current owner. Agents with no ratings in the window get no row. Running again the
// same (UTC) day replaces the rows of that day.

const DAY = 24 * 60 * 60 * 1000;
const WINDOW_DAYS = 7;

function weeklySummary(store, { now = new Date() } = {}) {
  const from = now.getTime() - WINDOW_DAYS * DAY;
  const byAgent = new Map();
  for (const t of store.listTickets()) {
    if (t.rating == null || t.owner_id == null) continue;
    const ratedAt = new Date(t.rated_at).getTime();
    if (ratedAt < from || ratedAt > now.getTime()) continue;
    byAgent.set(t.owner_id, [...(byAgent.get(t.owner_id) || []), t.rating]);
  }
  const written = [];
  for (const [agentId, scores] of byAgent) {
    const average = Math.round((scores.reduce((a, b) => a + b, 0) / scores.length) * 100) / 100;
    const row = {
      agent_id: agentId,
      period_start: new Date(from).toISOString(),
      period_end: now.toISOString(),
      ratings: scores.length,
      average,
    };
    store.saveAgentSummary(row);
    written.push(row);
  }
  return written;
}

module.exports = { weeklySummary, WINDOW_DAYS };
```

